class Solution {
    public int coinChange(int[] coins, int amount) {
        // 初始化dp，设为一个不可能的大数
        int[] dp = new int[amount + 1];
        int INF = amount + 1;
        for (int i = 1; i <= amount; i++) {
            dp[i] = INF;
        }
        dp[0] = 0;

        // 遍历每个金额
        for (int i = 1; i <= amount; i++) {
            // 遍历每种硬币
            for (int coin : coins) {
                if (coin <= i) {
                    dp[i] = Math.min(dp[i], dp[i - coin] + 1);
                }
            }
        }

        // 还是INF说明凑不出
        return dp[amount] == INF ? -1 : dp[amount];
    }
}
